export type AnchorPluginPdas = {
  globalConfig: typeof findGlobalConfigPda;
  eventAuthority: typeof findEventAuthorityPda;
  payoutRegistry: typeof findPayoutRegistryPda;
  pool: typeof findPoolPda;
  initialRedemptionBatch: typeof findInitialRedemptionBatchPda;
  poolVaultAccount: typeof findPoolVaultAccountPda;
  poolPstVault: typeof findPoolPstVaultPda;
};

export type AnchorPluginRequirements = ClientWithRpc<
  GetAccountInfoApi & GetMultipleAccountsApi
> &
  ClientWithPayer &
  ClientWithTransactionPlanning &
  ClientWithTransactionSending;

export function anchorProgram() {
  return <T extends AnchorPluginRequirements>(
    client: T
  ): ExtendedClient<T, { anchor: AnchorPlugin }> => {
    return extendClient(client, {
      anchor: <AnchorPlugin>{
        accounts: {
          drawCycle: addSelfFetchFunctions(client, getDrawCycleCodec()),
          globalConfig: addSelfFetchFunctions(client, getGlobalConfigCodec()),
          payoutRegistry: addSelfFetchFunctions(
            client,
            getPayoutRegistryCodec()
          ),
          pendingRedemption: addSelfFetchFunctions(
            client,
            getPendingRedemptionCodec()
          ),
          prizePool: addSelfFetchFunctions(client, getPrizePoolCodec()),
          redemptionBatch: addSelfFetchFunctions(
            client,
            getRedemptionBatchCodec()
          ),
          ticketRegistry: addSelfFetchFunctions(
            client,
            getTicketRegistryCodec()
          ),
          userWinnings: addSelfFetchFunctions(client, getUserWinningsCodec()),
        },
        instructions: {
          acceptAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAcceptAdminInstructionAsync(input)
            ),
          adminForceUnlockDraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminForceUnlockDrawInstructionAsync(input)
            ),
          adminVoidPayoutRegistry: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getAdminVoidPayoutRegistryInstructionAsync(input)
            ),
          buyBonds: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getBuyBondsInstructionAsync(input)
            ),
          cancelAdminNomination: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCancelAdminNominationInstructionAsync(input)
            ),
          claimNonReinvestedWinnings: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimNonReinvestedWinningsInstructionAsync(input)
            ),
          claimRedemption: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClaimRedemptionInstructionAsync(input)
            ),
          closeExpiredRedemption: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCloseExpiredRedemptionInstruction(input)
            ),
          closePool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getClosePoolInstructionAsync(input)
            ),
          crankClosePayoutRegistry: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCrankClosePayoutRegistryInstructionAsync(input)
            ),
          crankCloseRedemptionBatch: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCrankCloseRedemptionBatchInstructionAsync(input)
            ),
          crankRebindExpiredRandomness: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCrankRebindExpiredRandomnessInstructionAsync(input)
            ),
          crankSubmitRedemptionBatch: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCrankSubmitRedemptionBatchInstructionAsync(input)
            ),
          createPool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getCreatePoolInstructionAsync(input)
            ),
          enableImpairedMode: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getEnableImpairedModeInstructionAsync(input)
            ),
          harvestYieldAndCommit: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getHarvestYieldAndCommitInstructionAsync(input)
            ),
          initializeGlobal: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeGlobalInstructionAsync(input)
            ),
          initializeHumaLender: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getInitializeHumaLenderInstructionAsync(input)
            ),
          nominateAdmin: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getNominateAdminInstructionAsync(input)
            ),
          pausePool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPausePoolInstructionAsync(input)
            ),
          prepareDraw: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getPrepareDrawInstruction(input)
            ),
          recapitalizePool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRecapitalizePoolInstructionAsync(input)
            ),
          reinvestWinnings: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getReinvestWinningsInstructionAsync(input)
            ),
          resizeRegistry: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getResizeRegistryInstruction({
                ...input,
                payer: input.payer ?? client.payer,
              })
            ),
          revealAndPickWinners: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getRevealAndPickWinnersInstructionAsync(input)
            ),
          sellBonds: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSellBondsInstructionAsync(input)
            ),
          setPrizeTiers: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSetPrizeTiersInstructionAsync(input)
            ),
          settleRedemptionBatch: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getSettleRedemptionBatchInstructionAsync(input)
            ),
          unpausePool: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUnpausePoolInstructionAsync(input)
            ),
          updateGlobalConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdateGlobalConfigInstructionAsync(input)
            ),
          updatePoolConfig: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getUpdatePoolConfigInstructionAsync(input)
            ),
          withdrawFees: (input) =>
            addSelfPlanAndSendFunctions(
              client,
              getWithdrawFeesInstructionAsync(input)
            ),
        },
        pdas: {
          globalConfig: findGlobalConfigPda,
          eventAuthority: findEventAuthorityPda,
          payoutRegistry: findPayoutRegistryPda,
          pool: findPoolPda,
          initialRedemptionBatch: findInitialRedemptionBatchPda,
          poolVaultAccount: findPoolVaultAccountPda,
          poolPstVault: findPoolPstVaultPda,
        },
        identifyAccount: identifyAnchorAccount,
        identifyInstruction: identifyAnchorInstruction,
        parseInstruction: parseAnchorInstruction,
      },
    });
  };
}

type MakeOptional<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;
